const keys=new Set(),assets={},settings={darkness:.68,blood:true,shake:!matchMedia('(prefers-reduced-motion: reduce)').matches};
let game=new Game(),mode='menu',prior='play',camera={x:0,y:0},view={w:1000,h:625},last=0,clock=0,shake=0,hitStop=0,lines=[],afterDialog=null,toastEnd=0,subtitleEnd=0,flashEnd=0,attackHeld=false,pointerAim=null,loaded=false,connected=new Set(),selected=null,sound=true,audioCtx=null,master=null,hum=null,footTime=0;
let chapter=0,totals={kills:0,time:0},notes=new Set(),savedGame=null,revision=0,saveReady=false,saving=false,pendingSave=null,saveConflict=false,completed=false,relayInput=[],journalPrior='play',confirmPrior='menu',ambienceAt=5,heartbeatAt=0,storyPartner='yui',storyNumber=0,storyCount=0,cinematic=null,shotElapsed=0,shotIndex=0,shotDuration=0,animationTime=0,speakingCharacter='narrator',speakingDuration=0,bossImpactPlayed=false;
