function resize(){const r=$('stage').getBoundingClientRect();view.w=1000;view.h=1000*r.height/Math.max(1,r.width);canvas.width=view.w;canvas.height=Math.round(view.h);ctx.imageSmoothingEnabled=false;}
new ResizeObserver(resize).observe($('stage'));
function setMode(next){if(next!=='wires')cancelWireDrag();mode=next;$('talking-hero').hidden=true;$('talking-other').hidden=true;$('boss-hud').hidden=true;keys.clear();attackHeld=false;pointerAim=null;const modes={menu:'menu',dialog:'dialog',wires:'wires',paused:'pause',death:'death',victory:'victory',journal:'journal',relay:'relay',confirm:'confirm',hiding:'hiding'};for(const [id,m]of Object.entries(modes))$(id).hidden=m!==mode;$('hud').hidden=['menu','dialog','hiding'].includes(mode);$('touch').hidden=mode!=='play';$('prompt').hidden=true;$('pause').disabled=['menu','death','victory','confirm','journal'].includes(mode);if(mode==='play')canvas.focus({preventScroll:true});if(mode==='pause'){$('restart').disabled=!!cinematic||!!hiding;$('resume').focus();}if(mode==='death')$('retry').focus();if(mode==='victory')$('again').focus();if(mode==='journal')$('journal-close').focus();if(mode==='relay')$('relay-close').focus();if(mode==='confirm')$('confirm-cancel').focus();}
function message(text,duration=3){setText($('toast'),text);$('toast').hidden=false;toastEnd=clock+duration;}
function subtitle(text,duration=5){setText($('subtitle'),text);$('subtitle').hidden=false;subtitleEnd=clock+duration;}
function dialogue(sequence,callback){cinematic=null;$('portrait-hero').hidden=false;$('story-backdrop').style.transform='';$('story-backdrop').style.backgroundPosition='';$('dialog').classList.toggle('cinematic',false);$('cinematic-boss').hidden=true;$('scene-auto').hidden=true;$('scene-progress').hidden=true;lines=sequence.slice();storyCount=lines.length;storyNumber=0;afterDialog=callback||null;setMode('dialog');nextLine();}
function nextLine(){if(cinematic){advanceCutscene();return;}if(lines.length){const [speaker,line]=lines.shift();storyNumber++;const portrait=portraitFor(speaker),isCharacter=portrait!=='narrator';if(portrait==='yui'||portrait==='teacher')storyPartner=portrait;setText($('speaker'),speaker==='YOU'?'REINA':speaker);setText($('line'),line);startTalking(speaker,line);setText($('speaker-role'),portrait==='hero'?'HIGH-SCHOOL STUDENT':portrait==='yui'?'CLASSMATE · HIGH SCHOOL':portrait==='teacher'?'MS MIZUNO · FACULTY':'AFTER THE LAST BELL');setText($('scene-caption'),`${CHAPTERS[chapter].title} / ${String(storyNumber).padStart(2,'0')} — ${String(storyCount).padStart(2,'0')}`);$('portrait-hero').classList.toggle('speaking',portrait==='hero');$('portrait-hero').classList.toggle('quiet',portrait!=='hero');$('portrait-other').src=`assets/portrait-${storyPartner}.webp`;$('portrait-other').classList.toggle('speaking',portrait===storyPartner);$('portrait-other').classList.toggle('quiet',portrait!==storyPartner);$('portrait-other').hidden=!isCharacter;$('dialog').classList.toggle('narration',!isCharacter);$('story-backdrop').style.backgroundImage=`url("assets/${CHAPTERS[chapter].image}.jpg")`;setText($('next'),lines.length?'CONTINUE ↵':'CONTINUE TO ESCAPE ↵');$('next').focus();}else{setMode('play');const callback=afterDialog;afterDialog=null;callback?.();}}
function skipStory(){if(mode!=='dialog')return;if(cinematic){finishCutscene();return;}lines=[];nextLine();}
function playCutscene(id,callback){const scene=CUTSCENES[id];cinematic={...scene,id,callback,auto:true};shotIndex=-1;setMode('dialog');$('dialog').classList.toggle('cinematic',true);$('scene-auto').hidden=false;$('scene-progress').hidden=false;setText($('scene-auto'),'AUTO ON');$('scene-auto').setAttribute('aria-pressed','true');advanceCutscene();}
function advanceCutscene(){if(!cinematic)return;shotIndex++;if(shotIndex>=cinematic.shots.length){finishCutscene();return;}const shot=cinematic.shots[shotIndex];shotElapsed=0;shotDuration=Math.max(shot.seconds,shot.text.length/26+1);setText($('speaker'),shot.speaker==='YOU'?'REINA':shot.speaker);setText($('line'),shot.text);startTalking(shot.speaker,shot.text);bossImpactPlayed=false;setText($('speaker-role'),'STORY SEQUENCE');setText($('scene-caption'),`${cinematic.title} / ${String(shotIndex+1).padStart(2,'0')} — ${String(cinematic.shots.length).padStart(2,'0')}`);$('story-backdrop').style.backgroundImage=`url("assets/${shot.image}.jpg")`;$('story-backdrop').style.backgroundPosition=shot.position;$('dialog').classList.toggle('narration',false);$('portrait-hero').hidden=shot.focus!=='hero';$('portrait-other').hidden=!['yui','teacher'].includes(shot.focus);$('portrait-hero').classList.toggle('speaking',true);$('portrait-hero').classList.toggle('quiet',false);$('portrait-other').classList.toggle('speaking',true);$('portrait-other').classList.toggle('quiet',false);if(['yui','teacher'].includes(shot.focus))$('portrait-other').src=`assets/portrait-${shot.focus}.webp`;$('cinematic-boss').hidden=shot.focus!=='boss';if(shot.focus==='boss')paintBossShot(shot.pose||0);setText($('next'),shotIndex===cinematic.shots.length-1?cinematic.endLabel+' ↵':'NEXT SHOT ↵');$('scene-progress-bar').style.width='0%';$('next').focus();if(shot.sound==='metal'){tone(140,.65,.07,'sawtooth');tone(520,.8,.035,'triangle');}if(shot.sound==='thud'&&shot.focus!=='boss')tone(38,.8,.18,'triangle');if(shot.sound==='rain')tone(63,1.5,.03,'sine');}
function paintBossShot(pose){const c=$('cinematic-boss'),g=c.getContext('2d'),f=assets.bossMeta.frames[pose];c.width=600;c.height=650;g.clearRect(0,0,600,650);const scale=.86;g.imageSmoothingEnabled=false;g.drawImage(assets.boss,f.x,f.y,f.w,f.h,300-f.anchorX*scale,620-f.anchorY*scale,f.w*scale,f.h*scale);}
function finishCutscene(){if(!cinematic)return;const callback=cinematic.callback;cinematic=null;$('dialog').classList.toggle('cinematic',false);$('cinematic-boss').hidden=true;$('portrait-hero').hidden=false;$('scene-auto').hidden=true;$('scene-progress').hidden=true;$('story-backdrop').style.backgroundPosition='';setMode('play');callback?.();}
function prepareTalkTexture(image,meta,character){const c=document.createElement('canvas');c.width=meta.width;c.height=meta.height;const g=c.getContext('2d');g.drawImage(image,0,0);const pixels=g.getImageData(0,0,c.width,c.height);keySpriteBacking(pixels.data,c.width,c.height,meta.cellWidth,meta.cellHeight);blackMatteSprite(pixels.data,c.width,c.height,character);g.putImageData(pixels,0,0);return c;}
function startTalking(speaker,text){animationTime=0;speakingCharacter=portraitFor(speaker);speakingDuration=speechDuration(text);}
function renderTalkingPortrait(id,character,speaking,offset){const atlas=assets[character+'TalkMeta'],im=assets[character+'Talk'];if(!atlas||!im)return;const c=$(id),g=c.getContext('2d');const frame=expressionFrame(animationTime,speaking,speakingDuration,offset),f=atlas.frames[frame];if(c.width!==768){c.width=768;c.height=768;}g.clearRect(0,0,768,768);g.imageSmoothingEnabled=true;
 // Registration retains an identical eye line and scale through mouth/blink swaps.
 const motion=settings.shake?Math.sin(animationTime*1.65+offset)*1.5:0;g.save();g.translate(0,motion);g.globalAlpha=speaking?1:.61;g.drawImage(im,f.x,f.y,f.w,f.h,f.dx||0,f.dy||0,768,768);g.restore();}
function tickCharacterAnimation(dt){if(mode!=='dialog')return;animationTime+=dt;const heroVisible=!$('portrait-hero').hidden,otherVisible=!$('portrait-other').hidden;const partner=cinematic?cinematic.shots[shotIndex]?.focus:storyPartner;const heroAnimated=heroVisible&&!!assets.heroTalk,otherAnimated=otherVisible&&partner==='yui'&&!!assets.yuiTalk;$('talking-hero').hidden=!heroAnimated;$('talking-other').hidden=!otherAnimated;$('portrait-hero').classList.toggle('replaced-by-animation',heroAnimated);$('portrait-other').classList.toggle('replaced-by-animation',otherAnimated);if(heroAnimated)renderTalkingPortrait('talking-hero','hero',speakingCharacter==='hero',0);if(otherAnimated)renderTalkingPortrait('talking-other','yui',speakingCharacter==='yui',1.2);
 if(cinematic&&cinematic.shots[shotIndex]?.focus==='boss'){const pose=bossScenePose(cinematic.id,animationTime);paintBossShot(pose);if(cinematic.id==='bossIntro'&&animationTime>=1.9&&!bossImpactPlayed){bossImpactPlayed=true;tone(38,.8,.18,'triangle');$('cinematic-boss').classList.toggle('boss-impact',settings.shake);}if(animationTime>2.25)$('cinematic-boss').classList.toggle('boss-impact',false);}}

function tickCutscene(dt){if(!cinematic||mode!=='dialog')return;if(cinematic.auto)shotElapsed+=dt;const progress=Math.min(1,shotElapsed/shotDuration);$('scene-progress-bar').style.width=progress*100+'%';$('story-backdrop').style.transform=settings.shake?`scale(${1.02+progress*.035})`:'none';if(cinematic.auto&&shotElapsed>=shotDuration)advanceCutscene();}

function previewBossScene(){if(!loaded)return;const previous=chapter;chapter=2;playCutscene('bossIntro',()=>{chapter=previous;setMode('menu');});}
// Cinematic classroom hunt. All cue, animation and panic timing freezes on pause.
let hiding=null;
const hideNames=['teacher’s desk','window desks','back-row desks'];
function startHiding(done){hiding={done,phase:'intro',round:0,time:0,total:0,beat:0,next:2.4,spot:-1,broken:[],impact:0,lastCue:-1,panic:24,beats:[],lastTap:-9,slamSound:false,jumpSound:false};cinematic=null;setMode('hiding');$('hide-retry').hidden=true;$('hide-spots').hidden=true;$('hide-rhythm').hidden=true;setText($('hide-title'),'ROOM 2–B');setText($('hide-story'),'The door handle stops turning.');setText($('hide-status'),'');paintHiding();}
function chooseHidingPrompt(){const h=hiding;h.phase='choose';h.time=0;$('hide-rhythm').hidden=true;$('hide-spots').hidden=false;setText($('hide-title'),h.round?'MOVE. QUIETLY.':'GET DOWN.');setText($('hide-story'),h.round?'He turns toward the noise. Crawl to another hiding place.':'Reina clamps a hand over her mouth. He is listening.');setText($('hide-status'),'CHOOSE COVER');for(let i=0;i<3;i++){$('hide-spot-'+i).disabled=h.broken.includes(i);setText($('hide-spot-'+i),h.broken.includes(i)?'DESTROYED':hideNames[i].toUpperCase());}for(let i=0;i<3;i++)if(!h.broken.includes(i)){$('hide-spot-'+i).focus();break;}}
function chooseHidingSpot(i){if(mode!=='hiding'||hiding.phase!=='choose'||hiding.broken.includes(i))return;const h=hiding;Object.assign(h,{spot:i,phase:'rhythm',time:0,beat:0,next:2.4,lastCue:-1,lastTap:-9,slamSound:false});h.beats=[2.4];for(const gap of [1.18,.98,1.24,1.06,1.15])h.beats.push(h.beats.at(-1)+gap-h.round*.07);$('hide-spots').hidden=true;$('hide-rhythm').hidden=false;setText($('hide-title'),'HOLD YOUR BREATH');setText($('hide-story'),'Please… keep walking.');setText($('hide-status'),'Let each pulse reach the vertical marker. Then tap.');$('hide-tap').focus();}
function heartbeatResult(correct){const h=hiding;h.panic=Math.max(8,Math.min(100,h.panic+(correct?-13:38)));setText($('hide-status'),correct?'Steady. Stay silent.':'Your breath catches. He stops.');if(!correct){h.impact=.22;tone(155,.16,.045,'sawtooth');}if(h.panic>=100){failHiding();return;}h.beat++;if(h.beat>=h.beats.length){h.phase='smash';h.time=0;h.slamSound=false;$('hide-rhythm').hidden=true;setText($('hide-title'),'DON’T LOOK UP.');setText($('hide-story'),'His shadow falls across the desks.');setText($('hide-status'),'');}else h.next=h.beats[h.beat];}
function tapHeartbeat(){if(mode!=='hiding'||hiding?.phase!=='rhythm')return;const h=hiding;if(h.time<1.2||h.time-h.lastTap<.16)return;h.lastTap=h.time;if(Math.abs(h.time-h.next)<=.22){tone(52,.1,.07,'sine');heartbeatResult(true);}else{h.panic=Math.min(100,h.panic+32);h.impact=.18;setText($('hide-status'),'Too fast. Slow your breathing.');if(h.panic>=100)failHiding();}}
function failHiding(){const h=hiding;h.phase='caught';h.time=0;h.jumpSound=false;$('hide-rhythm').hidden=true;$('hide-spots').hidden=true;setText($('hide-title'),'');setText($('hide-story'),'The footsteps stop.');setText($('hide-status'),'');}
function tickHiding(dt){if(mode!=='hiding'||!hiding)return;const h=hiding;h.time+=dt;h.total+=dt;h.impact=Math.max(0,h.impact-dt);
 if(h.phase==='intro'){if(h.time>1.8&&!h.slamSound){h.slamSound=true;h.impact=.8;tone(38,.65,.14,'sawtooth');setText($('hide-story'),'The hinges tear out of the wall.');}if(h.time>3.4)setText($('hide-story'),'Reina ducks beneath a desk. Don’t breathe.');if(h.time>5.5)chooseHidingPrompt();}
 else if(h.phase==='rhythm'){const delta=h.next-h.time;setText($('hide-count'),`BREATH CONTROL  ${h.beat} / ${h.beats.length}`);$('hide-panic').style.width=h.panic+'%';setText($('hide-bpm'),String(Math.round(64+h.panic*.9)));$('hide-tap').classList.toggle('on-beat',Math.abs(delta)<=.22);if(delta<=.16&&h.lastCue!==h.beat){h.lastCue=h.beat;tone(48,.14,.09,'sine');}if(delta<-.22)heartbeatResult(false);paintECG();}
 else if(h.phase==='smash'){if(h.time>.85&&!h.slamSound){h.slamSound=true;h.impact=1;h.panic=Math.min(84,h.panic+12);tone(29,.8,.15,'sawtooth');tone(94,.45,.06,'triangle');setText($('hide-story'),['Wood splinters inches above her head.','The windows burst. Plaster rains onto her shoulders.','He drives both fists through the outer wall.'][h.round]);}if(h.time>3.6){h.broken.push(h.spot);h.round++;if(h.round===3){h.phase='escape';h.time=0;setText($('hide-title'),'RUN.');setText($('hide-story'),'Through the broken wall. Before he turns around.');}else chooseHidingPrompt();}}
 else if(h.phase==='escape'&&h.time>3.2){const done=h.done;hiding=null;setMode('play');done();return;}
 else if(h.phase==='caught'){if(h.time>.75&&!h.jumpSound){h.jumpSound=true;h.impact=1;tone(49,.4,.18,'sawtooth');tone(720,.12,.07,'sawtooth');setText($('hide-story'),'');}if(h.time>2.1){setText($('hide-title'),'FOUND.');setText($('hide-story'),'One gasp was all he needed.');setText($('hide-status'),'REINA DID NOT SURVIVE');$('hide-retry').hidden=false;}}
 paintHiding();}
function paintECG(){const h=hiding,g=$('hide-ecg').getContext('2d');g.clearRect(0,0,900,120);g.fillStyle='#060e10';g.fillRect(0,0,900,120);g.strokeStyle='#14262a';g.lineWidth=1;g.beginPath();for(let x=0;x<=900;x+=25){g.moveTo(x,0);g.lineTo(x,120);}for(let y=10;y<120;y+=20){g.moveTo(0,y);g.lineTo(900,y);}g.stroke();g.fillStyle='rgba(181,219,206,.09)';g.fillRect(180-.22*170,0,.44*170,120);g.strokeStyle='#dcebe6';g.beginPath();g.moveTo(180,0);g.lineTo(180,120);g.stroke();const color=h.panic>65?'#ff4a4e':'#8bc9b6';g.strokeStyle=color;g.lineWidth=2.5;g.beginPath();for(let x=0;x<=900;x+=2){const t=h.time+(x-180)/170;let v=Math.sin(t*14)*1.5;for(const b of h.beats){const d=t-b;v+=-7*Math.exp(-1*((d+.13)/.04)**2)+16*Math.exp(-1*((d+.045)/.018)**2)-(32+h.panic*.35)*Math.exp(-1*(d/.025)**2)+21*Math.exp(-1*((d-.045)/.022)**2)-7*Math.exp(-1*((d-.18)/.08)**2);}const y=Math.max(4,Math.min(116,67+v));if(x===0)g.moveTo(x,y);else g.lineTo(x,y);}g.stroke();}
function hidingImage(g,im,zoom=1,pan=0){g.drawImage(im,500-500*zoom+pan,312.5-312.5*zoom,1000*zoom,625*zoom);}
function paintHiding(){if(!hiding||!assets.hideRoom)return;const h=hiding,g=$('hide-scene').getContext('2d');g.clearRect(0,0,1000,625);g.save();const t=h.time,slam=h.phase==='smash',caught=h.phase==='caught';if(settings.shake&&h.impact)g.translate(Math.sin(t*87)*13*h.impact,Math.cos(t*63)*9*h.impact);
 const fear=(h.phase==='intro'&&t>3.4)||(h.phase==='rhythm'&&(h.beat%3===1||h.panic>70))||(caught&&t<.75);if(fear){hidingImage(g,assets.hideReina,1.04+Math.sin(h.total*3)*.006,h.spot*7);}
 else if((caught&&t>=.75&&t<1.5)||(slam&&t>.25&&t<.85)){hidingImage(g,assets.hideJump,1+Math.max(0,t-(slam?.25:.75))*.8);}
 else{const tile=Math.min(3,h.round+(slam&&t>.85?1:0)),im=assets.hideRoom,w=im.width/2,ht=im.height/2;const zoom=1.06+Math.sin(h.total*.2)*.025;g.drawImage(im,(tile%2)*w,Math.floor(tile/2)*ht,w,ht,500-500*zoom,312.5-312.5*zoom,1000*zoom,625*zoom);
 if(h.phase!=='escape'){const pose=slam?(t<.85?2:3):h.phase==='intro'&&t<1.8?0:Math.floor(h.total*1.8)%2,f=assets.bossMeta.frames[pose],approach=h.phase==='rhythm'?Math.min(1,h.beat/6):.2,size=.48+approach*.28+(slam?.18:0),x=620+Math.sin(h.total*.5)*90+(slam?Math.sin(Math.min(1,t/.85)*Math.PI)*-70:0),y=505+(slam&&t>.85?25:Math.sin(h.total*3.6)*4);g.drawImage(assets.boss,f.x,f.y,f.w,f.h,x-f.anchorX*size,y-f.anchorY*size,f.w*size,f.h*size);}
 if(slam&&t>.85&&t<2.8){const a=t-.85;for(let j=0;j<32;j++){g.save();g.translate(480+Math.sin(j*9)*a*440,250+Math.cos(j*7)*a*220+a*a*100);g.rotate(j+a*4);g.globalAlpha=Math.max(0,1-a/2);g.drawImage(im,(j*37)%Math.floor(w-30),(j*59)%Math.floor(ht-30),25,20,-10,-8,20+j%15,16);g.restore();}g.fillStyle=`rgba(125,119,111,${Math.max(0,.35-a*.18)})`;g.fillRect(0,0,1000,625);}}
 // Darkness and letterboxing frame the illustrated shots without obscuring the ECG.
 g.fillStyle='rgba(0,0,0,.12)';g.fillRect(0,0,1000,625);g.fillStyle='#030406';g.fillRect(0,0,1000,32);g.fillRect(0,575,1000,50);if(caught&&t>=1.5){g.fillStyle='#030406';g.fillRect(0,0,1000,625);}g.restore();}
for(let i=0;i<3;i++)$('hide-spot-'+i).onclick=()=>chooseHidingSpot(i);
$('hide-tap').onpointerdown=e=>{e.preventDefault();tapHeartbeat();};$('hide-tap').onclick=e=>{if(e.detail===0)tapHeartbeat();};
$('hide-retry').onclick=()=>startHiding(hiding.done);
$('preview-hiding').onclick=()=>{if(loaded){initAudio();startHiding(()=>setMode('menu'));}};

function watchOpening(){if(!loaded)return;const previousChapter=chapter;chapter=0;storyPartner='yui';dialogue(PROLOGUE,()=>{chapter=previousChapter;setMode('menu');});}

function start(force=false){if(!loaded)return;if(!force&&(savedGame||chapter>0||game.time>5)){confirmPrior=mode;setMode('confirm');return;}chapter=0;totals={kills:0,time:0};notes=new Set();completed=false;enterChapter(0);}
function mapFor(n){return [MAP,INFIRMARY,COURTYARD][n];}
function locateChapter(){points.panel=game.map.panel;points.exit=game.map.exit;camera.x=game.player.x-view.w/2;camera.y=game.player.y-view.h/2;connected=game.power?new Set([0,1,2,3]):new Set();selected=null;footTime=game.time;setText($('chapter-label'),`CHAPTER 0${chapter+1} / ${CHAPTERS[chapter].title}`);setText($('chapter-flash').querySelector('span'),`CHAPTER 0${chapter+1}`);setText($('chapter-flash').querySelector('strong'),CHAPTERS[chapter].title);buildWires();updateHUD();}
function enterChapter(n,skipIntro=false){const previous=game.player;chapter=n;game=new Game(mapFor(n));if(n>0){game.player.medkits=Math.max(2,previous.medkits);game.player.hp=100;}locateChapter();checkpoint();initAudio();storyPartner='yui';if(skipIntro){setMode('play');$('chapter-flash').hidden=false;flashEnd=clock+2.6;message('CHECKPOINT · '+CHAPTERS[n].goal,6);return;}dialogue(n===0?[...PROLOGUE,...CHAPTERS[n].intro]:CHAPTERS[n].intro,()=>{$('chapter-flash').hidden=false;flashEnd=clock+2.6;message(n===0?'WASD move · J / click attack · Space dodge · E interact · H heal':'CHECKPOINT · Health restored · '+CHAPTERS[n].goal,7);});}
function checkpoint(){game.checkpoint=game.snapshot();queueSave();}
function queueSave(){pendingSave=saveEnvelope(chapter,game,totals,notes,completed);flushSave();}
function saveStatus(text,error=false){setText($('save-state'),text);setText($('status'),text);$('save-retry').hidden=!error;$('pause-save').hidden=!error;}
async function loadSave(){try{const r=await saveRequest('/api/save',{cache:'no-store'});if(!r.ok)throw Error('load');const data=await r.json();if(!Number.isInteger(data.revision)||data.revision<0||(data.save&&!validSave(data.save)))throw Error('invalid');revision=data.revision;savedGame=data.save;saveReady=true;saveConflict=false;$('continue').hidden=!savedGame;setText($('continue'),savedGame?.completed?'VIEW YOUR ENDING':`CONTINUE · CHAPTER 0${(savedGame?.chapter||0)+1}`);saveStatus(savedGame?'Checkpoint ready.':'Your escape will save at checkpoints.');if(pendingSave)flushSave();}catch{saveReady=false;saveStatus('Save connection unavailable. You can play, but progress is not saved yet.',true);}}
async function flushSave(){if(saving||!pendingSave||!saveReady||saveConflict)return;saving=true;const snapshot=pendingSave;pendingSave=null;saveStatus('Saving checkpoint…');try{const r=await saveRequest('/api/save',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,save:snapshot})});const data=await r.json();if(!r.ok){if(r.status===409){saveConflict=true;throw Error('conflict');}throw Error('save');}revision=data.revision;savedGame=snapshot;saveStatus(completed?'Escape complete · Ending saved.':'Checkpoint saved · You can continue later.');$('continue').hidden=false;}catch(e){pendingSave=pendingSave||snapshot;saveStatus(e.message==='conflict'?'A newer save exists in another session. Reload to load it; this session will not overwrite it.':'Checkpoint not saved. Retry the save connection from the title screen.',true);}finally{saving=false;}if(pendingSave&&!$('save-retry').hidden)return;if(pendingSave)flushSave();}
function continueGame(){if(!savedGame||!validSave(savedGame))return;chapter=savedGame.chapter;totals={...savedGame.totals};notes=new Set(savedGame.notes);completed=savedGame.completed;game=new Game(mapFor(chapter));game.reset(savedGame.checkpoint);game.checkpoint=structuredClone(savedGame.checkpoint);locateChapter();initAudio();if(completed)showEnding();else if(chapter===1&&game.flags.hidingPending){finishChapter();}else{setMode('play');message('Checkpoint restored. No one gets left behind.',5);}}
function showEnding(){const seconds=Math.floor(totals.time+game.time);setText($('result-kills'),totals.kills+game.kills);setText($('result-time'),`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`);setText($('ending-evidence'),notes.has('evidence')?'Your photographs reach the investigators. The ignored safety warning becomes public.':'The responders secure the school and begin investigating the chemical exposure.');setMode('victory');}
function finishChapter(){if(chapter===1&&!game.flags.hideSurvived){game.flags.hidingPending=true;checkpoint();startHiding(()=>{game.flags.hideSurvived=true;game.flags.hidingPending=false;checkpoint();finishChapter();});return;}if(chapter<2){const next=chapter+1;playCutscene(next===1?'infirmary':'courtyard',()=>{totals.time+=game.time;totals.kills+=game.kills;enterChapter(next,true);});}else{completed=true;game.checkpoint=game.snapshot();queueSave();dialogue([['YUI','Everyone’s through. Now you.'],['YOU','I told you I wasn’t leaving anyone behind.'],['DAWN · OUTSIDE THE SCHOOL','The responders seal the ventilation system and evacuate the survivors. The exposure is contained. Yui squeezes your hand as the last school bell runs out of power.']],showEnding);}}
function openJournal(){if(['dialog','wires','relay','confirm','death','hiding'].includes(mode))return;journalPrior=mode;const box=$('journal-content');box.replaceChildren();if(!notes.size){const p=document.createElement('p');setText(p,'No records collected yet. Look for ? and card markers. Notes explain what happened; the compass follows your next objective.');box.append(p);}for(const id of notes){const a=document.createElement('article'),h=document.createElement('h3'),p=document.createElement('p');setText(h,NOTES[id].title);setText(p,NOTES[id].text);a.append(h,p);box.append(a);}setMode('journal');}
function objectivePoint(){if(chapter===1&&!game.power){const item=game.map.items.find(i=>['medicine','card'].includes(i.id)&&!game.flags[i.id]);if(item)return item;}return game.power?points.exit:points.panel;}
function objectiveText(){if(chapter===0)return game.power?'Reach the east service shutter.':'Repair the east-classroom circuit.';if(chapter===1){if(!game.flags.medicine)return 'Find the trauma kit in the west ward.';if(!game.flags.card)return 'Find the maintenance card in the east ward.';return game.power?'Reach Yui at the east courtyard door.':'Enter the relay sequence at the east panel.';}if(!game.power)return 'Start the backup generator, northeast.';if(game.enemies.some(e=>e.kind==='boss'&&e.hp>0))return 'Survive the Headmaster. Dodge the red strike zone.';return game.charge<30?'Hold out while the gate motor charges.':'Clear the north gate and get out.';}
function chooseRelay(n){if(mode!=='relay')return;const order=[3,1,4,2];if(n!==order[relayInput.length]){relayInput=[];setText($('relay-feedback'),'Sequence reset. Follow 3 → 1 → 4 → 2.');tone(100,.1,.1);return;}relayInput.push(n);setText($('relay-feedback'),relayInput.join(' → '));tone(350+n*70,.1,.06);if(relayInput.length===4){game.restorePower();handleEvents();checkpoint();dialogue([['YUI','The service door is open. I’ll take the trauma kit and meet the others by the courtyard gate.'],['YOU','Keep them together. I’m right behind you.']]);}}

function togglePause(){if(mode==='pause'){setMode(prior);if(mode==='wires')focusWire();if(mode==='dialog')$('next').focus();}else if(['play','dialog','wires','relay','hiding'].includes(mode)){prior=mode;setMode('pause');if(pendingSave)flushSave();}else if(mode==='journal')setMode(journalPrior);}
function interaction(){if(mode!=='play')return;const p=game.player;for(const item of game.map.items||[]){if(game.flags[item.id]||Math.hypot(p.x-item.x,p.y-item.y)>110)continue;if(game.nearbyThreat(item.x,item.y,160)){message('Clear the infected nearby first.');return;}game.flags[item.id]=true;if(item.id==='medicine'){game.player.medkits+=2;game.player.hp=Math.min(100,game.player.hp+30);checkpoint();dialogue([['YOU','Trauma pack. Two dressings for me, and a clean bandage for Yui. Keep moving.']]);}else{notes.add(item.id);checkpoint();dialogue([[NOTES[item.id].title,NOTES[item.id].text]]);}return;}
 if(Math.hypot(p.x-points.panel.x,p.y-points.panel.y)<125){if(game.power){message(objectiveText());return;}if(game.nearbyThreat(points.panel.x,points.panel.y,220)){message('Clear the infected around the panel first.');return;}if(chapter===0){setMode('wires');buildWires();focusWire();}else if(chapter===1){if(!game.flags.medicine||!game.flags.card){message(objectiveText());return;}relayInput=[];setText($('relay-feedback'),'Waiting for input.');setMode('relay');}else{playCutscene('bossIntro',()=>{game.restorePower();game.flags.bossIntroSeen=true;checkpoint();handleEvents();subtitle('YUI · The gate motor needs thirty seconds. Watch that thing’s arms!',7);});}return;}
 if(Math.hypot(p.x-points.exit.x,p.y-points.exit.y)<120){if(!game.power){message(objectiveText());return;}if(chapter===2&&(game.charge<30||game.enemies.some(e=>e.kind==='boss'&&e.hp>0))){message(objectiveText());return;}if(game.nearbyThreat(points.exit.x,points.exit.y,150)){message('They’re too close. Clear space around the exit.');return;}game.escape();handleEvents();}}

const wireColors=['#ec5651','#f1c638','#6bba8f','#78a8f0'],symbols=['▲','■','●','◆'],rightOrder=[2,0,3,1];
let wireDrag=null;
