  if(active){add('rect',{x:to.x-12,y:to.y-10,width:24,height:20,rx:4,fill:wireColors[i],stroke:'#f4ead6','stroke-width':2});add('rect',{x:to.x+9,y:to.y-6,width:7,height:12,fill:'#c9c2ad'});}
