function endWireDrag(e){if(!wireDrag||wireDrag.pointerId!==e.pointerId)return;const drag=wireDrag,target=wireTarget(e),id=target?Number(target.dataset.index):null;cancelWireDrag();if(drag.moved&&id===drag.from){selected=drag.from;chooseWire('right',id);}else{selected=null;setText($('wire-feedback'),id!==null&&id!==drag.from?'Wrong socket — match the wire color and symbol.':'Wire released. Hold the plug and drag it into the matching socket.');tone(100,.09,.04,'triangle');drawWires();}}
