function focusWire(){$('left-terminals').querySelector('button:not(:disabled)')?.focus();}
function chooseWire(side,i){if(mode!=='wires'||connected.has(i))return;if(side==='left'){selected=i;setText($('wire-feedback'),`Wire ${['A','B','C','D'][i]} selected with keyboard. Activate its matching right socket.`);buildWires();$('right-terminals').querySelector('button:not(:disabled)')?.focus();return;}if(selected===null){setText($('wire-feedback'),'Select a terminal on the left first.');return;}if(selected!==i){setText($('wire-feedback'),'Wrong line. Match both the letter and symbol.');tone(100,.12,.1,'triangle');return;}connected.add(i);selected=null;buildWires();tone(400+i*90,.1,.07);setText($('wire-feedback'),`${connected.size} / 4 circuits connected.`);if(connected.size===4){game.restorePower();handleEvents();checkpoint();dialogue([['YUI · INTERCOM','Power’s back! The east service shutter is open. But that alarm woke up the corridor.'],['YOU','Then let’s give them something to chase. Keep going.']],()=>{message('CHECKPOINT REACHED · Health restored · Reach the east service shutter.',6);});}else focusWire();}
function updateHUD(){const p=game.player;setText($('health-text'),`${Math.ceil(p.hp)} / 100`);$('health-bar').style.width=p.hp+'%';$('stamina-bar').style.width=p.stamina+'%';setText($('medkits'),`H · ${p.medkits} MEDKIT${p.medkits===1?'':'S'}`);setText($('kills'),String(totals.kills+game.kills).padStart(2,'0')+' DOWN');setText($('mission-number'),`0${chapter+1} / ${CHAPTERS[chapter].title}`);setText($('objective'),objectiveText());const boss=game.enemies.find(e=>e.kind==='boss');$('boss-hud').hidden=chapter!==2||!game.power||mode!=='play';$('boss-health').style.width=(boss?Math.max(0,boss.hp)/boss.maxHp*100:0)+'%';setText($('charge-text'),`GATE CHARGE ${Math.floor(game.charge/30*100)}%${boss?.hp>0?' · DODGE, THEN STRIKE':' · HEADMASTER DOWN'}`);}

function handleEvents(){let bossFell=false;const events=game.events;game.events=[];for(const e of events){if(e.type==='kill'&&e.kind==='boss')bossFell=true;if(e.type==='saw')sawSound();if(e.type==='hit'){hitStop=.035;shake=settings.shake?5:0;tone(80,.075,.12,'sawtooth');}if(e.type==='hurt'){shake=settings.shake?9:0;tone(60,.2,.13,'triangle');}if(e.type==='heal'){tone(650,.15,.06);message('MEDKIT USED · +45 health');}if(e.type==='dodge')tone(160,.09,.04,'triangle');if(e.type==='power')tone(270,.4,.05);if(e.type==='warning')tone(110,.6,.08,'sawtooth');if(e.type==='slam'){shake=settings.shake?13:0;tone(35,.45,.24,'triangle');}if(e.type==='death')setMode('death');if(e.type==='victory')finishChapter();}if(bossFell&&!game.dead&&!game.flags.bossDefeatSeen){game.flags.bossDefeatSeen=true;checkpoint();playCutscene('bossDown',()=>message(objectiveText(),6));}}

function retry(){game.reset(game.checkpoint);locateChapter();setMode('play');message('Back at your checkpoint. Watch the red attack zones and time your dodge.',5);}

